import json
from typing import Any, Dict, List, Optional

class Message:
    def __init__(self, message_id: str, body: str, attributes: Optional[Dict[str, str]] = None):
        self.message_id = message_id
        self.body = body
        self.attributes = attributes if attributes is not None else {}

    def to_dict(self):
        return {
            "message_id": self.message_id,
            "body": self.body,
            "attributes": self.attributes
        }

    @classmethod
    def from_sqs_message(cls, sqs_message: Dict[str, Any]):
        message_id = sqs_message.get("MessageId") or sqs_message.get("MessageId") # For SQS, MessageId can be in different places
        body = sqs_message.get("Body", "{}")
        attributes = sqs_message.get("MessageAttributes", {})
        # Normalize SQS MessageAttributes to a simpler dict
        normalized_attributes = {
            k: v.get("StringValue") for k, v in attributes.items() if v.get("StringValue")
        }
        return cls(message_id=message_id, body=body, attributes=normalized_attributes)

class PublishResponse:
    def __init__(self, message_id: str, sequence_number: Optional[str] = None):
        self.message_id = message_id
        self.sequence_number = sequence_number

    def to_dict(self):
        return {
            "message_id": self.message_id,
            "sequence_number": self.sequence_number
        }

class BatchPublishRequest:
    def __init__(self, messages: List[Dict[str, Any]]):
        self.messages = messages

    def to_sns_entries(self):
        entries = []
        for i, msg in enumerate(self.messages):
            entries.append({
                'Id': msg.get('Id', str(i)),
                'Message': json.dumps(msg.get('Message')),
                'Subject': msg.get('Subject', 'Batch Message'),
                'MessageAttributes': {
                    k: {'DataType': 'String', 'StringValue': str(v)} 
                    for k, v in msg.get('MessageAttributes', {}).items()
                }
            })
        return entries

class BatchPublishResponse:
    def __init__(self, successful: List[Dict[str, str]], failed: List[Dict[str, Any]]):
        self.successful = successful
        self.failed = failed

    def to_dict(self):
        return {
            "successful": self.successful,
            "failed": self.failed
        }

import boto3
import json
from messaging_client import get_sqs_dead_letter_queue_url

def send_to_dead_letter_queue(message_body: dict, original_message_id: str, error_details: str):
    """
    Sends a failed message to an AWS SQS Dead-Letter Queue.
    """
    sqs_client = boto3.client('sqs')
    dlq_url = get_sqs_dead_letter_queue_url()

    try:
        message_attributes = {
            'OriginalMessageId': {
                'DataType': 'String',
                'StringValue': original_message_id
            },
            'ErrorDetails': {
                'DataType': 'String',
                'StringValue': error_details
            }
        }

        response = sqs_client.send_message(
            QueueUrl=dlq_url,
            MessageBody=json.dumps(message_body),
            MessageAttributes=message_attributes
        )
        print(f"Message sent to DLQ: {response['MessageId']}")
        return response
    except Exception as e:
        print(f"Error sending message to DLQ: {e}")
        raise

if __name__ == "__main__":
    failed_payload = {"data": "corrupted_data", "attempt": 3}
    original_id = "some-original-message-id-123"
    error_info = "Processing failed due to schema mismatch."
    send_to_dead_letter_queue(failed_payload, original_id, error_info)

import boto3
import json
from typing import List, Dict, Any
from messaging_client import get_sns_topic_arn
from messaging_models import BatchPublishRequest, BatchPublishResponse

def batch_publish_events(messages: List[Dict[str, Any]]):
    """
    Publishes a batch of JSON events to an AWS SNS topic.
    Each message dict in the list should contain:
    - 'Id': A unique identifier for the message in the batch (string, required).
    - 'Message': The actual message payload (dict, required).
    - 'Subject': (Optional) Subject for the message.
    - 'MessageAttributes': (Optional) Attributes for the message (dict).
    """
    sns_client = boto3.client('sns')
    topic_arn = get_sns_topic_arn()

    batch_request = BatchPublishRequest(messages)
    sns_entries = batch_request.to_sns_entries()

    if not sns_entries:
        print("No messages to publish in batch.")
        return BatchPublishResponse(successful=[], failed=[])

    try:
        response = sns_client.publish_batch(
            TopicArn=topic_arn,
            PublishBatchRequestEntries=sns_entries
        )

        successful = response.get('Successful', [])
        failed = response.get('Failed', [])

        print(f"Successfully published {len(successful)} messages in batch.")
        for msg in successful:
            print(f"  Message ID: {msg.get('MessageId')}, Entry ID: {msg.get('Id')}")
        if failed:
            print(f"Failed to publish {len(failed)} messages in batch.")
            for msg in failed:
                print(f"  Entry ID: {msg.get('Id')}, Code: {msg.get('Code')}, Message: {msg.get('Message')}")

        return BatchPublishResponse(successful=successful, failed=failed)

    except Exception as e:
        print(f"Error publishing batch messages: {e}")
        raise

if __name__ == "__main__":
    test_batch_messages = [
        {
            "Id": "msg1",
            "Message": {"order_id": "A001", "status": "shipped"},
            "Subject": "Order Shipped",
            "MessageAttributes": {"type": "order"}
        },
        {
            "Id": "msg2",
            "Message": {"user_id": "U002", "action": "login"},
            "Subject": "User Activity",
            "MessageAttributes": {"type": "user_activity", "priority": "high"}
        },
        {
            "Id": "msg3",
            "Message": {"product_id": "P003", "inventory": 100},
            "Subject": "Inventory Update",
        }
    ]
    batch_publish_events(test_batch_messages)

import boto3
import json
import os
import datetime

def summarize_message_processing_result(message_id: str, status: str, details: dict):
    """
    Summarizes message processing results by logging them to AWS CloudWatch Logs.
    This function simulates sending a structured log event.
    """
    log_group_name = os.environ.get("AWS_CLOUDWATCH_LOG_GROUP", "/aws/message_processing_logs")
    log_stream_name = os.environ.get("AWS_CLOUDWATCH_LOG_STREAM", "message_summaries")

    # Initialize CloudWatch Logs client
    logs_client = boto3.client('logs')

    log_event = {
        "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "message_id": message_id,
        "status": status,
        "details": details
    }

    try:
        # Ensure log group and stream exist (idempotent operations)
        try:
            logs_client.create_log_group(logGroupName=log_group_name)
        except logs_client.exceptions.ResourceAlreadyExistsException:
            pass # Log group already exists

        try:
            logs_client.create_log_stream(logGroupName=log_group_name, logStreamName=log_stream_name)
        except logs_client.exceptions.ResourceAlreadyExistsException:
            pass # Log stream already exists

        # Get the sequence token for the put_log_events call
        response = logs_client.describe_log_streams(
            logGroupName=log_group_name,
            logStreamNamePrefix=log_stream_name
        )
        sequence_token = None
        if 'logStreams' in response and len(response['logStreams']) > 0:
            sequence_token = response['logStreams'][0].get('uploadSequenceToken')

        # Put the log event
        if sequence_token:
            put_response = logs_client.put_log_events(
                logGroupName=log_group_name,
                logStreamName=log_stream_name,
                logEvents=[
                    {
                        'timestamp': int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000),
                        'message': json.dumps(log_event)
                    },
                ],
                sequenceToken=sequence_token
            )
        else:
            put_response = logs_client.put_log_events(
                logGroupName=log_group_name,
                logStreamName=log_stream_name,
                logEvents=[
                    {
                        'timestamp': int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000),
                        'message': json.dumps(log_event)
                    },
                ],
            )

        print(f"Log event for message {message_id} sent to CloudWatch Logs.")
        return put_response

    except Exception as e:
        print(f"Error sending log event to CloudWatch: {e}")
        raise

if __name__ == "__main__":
    summarize_message_processing_result(
        message_id="msg-summary-123", 
        status="completed", 
        details={
            "processor": "order_processor", 
            "duration_ms": 150,
            "items_processed": 5
        }
    )

import boto3
import json
import datetime
from typing import Dict, Any
from messaging_client import get_dynamodb_client, get_dynamodb_table_name

def persist_message_record(message_id: str, payload: Dict[str, Any], processing_status: str, timestamp: str = None) -> Dict[str, Any]:
    """
    Persists processed message records to AWS DynamoDB for later lookup.
    """
    dynamodb_client = get_dynamodb_client()
    table_name = get_dynamodb_table_name()

    if timestamp is None:
        timestamp = datetime.datetime.now(datetime.timezone.utc).isoformat()

    item = {
        'message_id': {'S': message_id},
        'timestamp': {'S': timestamp},
        'processing_status': {'S': processing_status},
        'payload': {'S': json.dumps(payload)}
    }

    try:
        response = dynamodb_client.put_item(
            TableName=table_name,
            Item=item
        )
        print(f"Message record for {message_id} persisted to DynamoDB.")
        return response
    except Exception as e:
        print(f"Error persisting message record to DynamoDB: {e}")
        raise

def get_message_record(message_id: str) -> Dict[str, Any]:
    """
    Retrieves a processed message record from AWS DynamoDB.
    """
    dynamodb_client = get_dynamodb_client()
    table_name = get_dynamodb_table_name()

    try:
        response = dynamodb_client.get_item(
            TableName=table_name,
            Key={
                'message_id': {'S': message_id}
            }
        )
        item = response.get('Item')
        if item:
            # Deserialize item from DynamoDB format
            deserialized_item = {
                k: v['S'] if 'S' in v else v
                for k, v in item.items()
            }
            # Deserialize the payload string back to a dictionary
            if 'payload' in deserialized_item:
                deserialized_item['payload'] = json.loads(deserialized_item['payload'])
            print(f"Retrieved message record for {message_id} from DynamoDB.")
            return deserialized_item
        else:
            print(f"No record found for message ID: {message_id}")
            return {}
    except Exception as e:
        print(f"Error retrieving message record from DynamoDB: {e}")
        raise

if __name__ == "__main__":
    test_message_id = "audit-msg-456"
    test_payload = {"data": "processed_data_content", "source": "consumer_app"}
    test_status = "SUCCESS"

    # Persist a record
    persist_message_record(test_message_id, test_payload, test_status)

    # Retrieve the record
    retrieved_record = get_message_record(test_message_id)
    print("\nRetrieved Record:")
    print(json.dumps(retrieved_record, indent=2))
